INSERT INTO tmp_segfac_2025 (n, facultad, s1, s2, descripcion) VALUES
(14, 'Arquitectura', 4.00, 3.00, '1. XI Congreso Técnico Internacional de Arquitectura. Innovación y Tecnología para Ciudades Inteligentes. (14 y 15 de mayo de 2025)\n2. I Encuentro Previo a la Semana Colombo China (24 de Febrero de 2025)\n3. Lanzamiento de Diplomados (14 de marzo)\n4. III Encuentro Internacional de la Construcción (9 de abril de 2025)\n5. Seminario Internacional de Patrimonio\n6. II Encuentro Previo a la Semana Colombo China (3 de Abril de 2025)\n7. III Encuentro Previo a la Semana Colombo China (13 de mayo de 2025)'),
(14, 'Bellas Artes', 2.00, 7.00, '1. Edgardo Trigo, del Centro Cultural María Élida Marquizo de Uruguay, participó en el evento “Primer Festival Internacional del Tambor – Taller Rítmicas del Uruguay aplicadas a la Percusión”, realizado el 24 de febrero de 2025, dirigido al Programa de Licenciatura en Música y Música, en modalidad virtual.\n\n2. Lido Pimienta, artista colombiana residente en Canadá, intervino en el evento “Panel Fugas de un Carnaval”, llevado a cabo el 5 de marzo de 2025, para el Programa de Artes Plásticas, en modalidad presencial.\n\n3. Taras Filenko, de Ucrania, desarrolló el Taller de Improvisación – Piano el 12 de agosto de 2025, dirigido al Programa de Licenciatura en Música y Música, en modalidad presencial.\n\n4. Dylan Porcel, del Conservatorio Superior de Música de Granada de España, realizó una visita de intercambio estudiantil el 26 de agosto de 2025, articulada con el Programa de Licenciatura en Música y Música, en modalidad presencial.\n\n5. Fernando Tapias, especialista Casio para Centroamérica y Suramérica, participó en el evento “Gran Lanzamiento Celviano 2025”, efectuado el 18 de septiembre de 2025, orientado al Programa de Licenciatura en Música y Música, en modalidad presencial.\n\n6. Geoffrey Haydon, de Estados Unidos, ofreció un Concierto / Taller de Piano el 20 de septiembre de 2025, dirigido al Programa de Licenciatura en Música y Música, en modalidad presencial.\n\n7. Danza: Encuentro Colombo - Alemán,'),
(14, 'Ciencias Básicas', 3.00, 8.00, '2025-1\n1. Dia Internacional de la Luz\n2. Dia Internacional de las Matemáticas\n3. Curso teorico practico de Quimiometria aplicada al area Biologíca\n\n 2025-2 \n1, XXI EIMAT 2025\n2 Coloquio de Matemáticas\n3.Dia del Físico\n4. Dia del Biologo\n5. Semana Colombo China\n6. Encuentro Integración regional para la Eduacción ambiental de ecosistemas marino costero hacia una agenda mesoamericano\n7. Coloquio de Fisica \n8. Sintesis y caracterización morfologica, estructural y electroquimica de nuevos materiales con aplicaciones energeticas'),
(14, 'Ciencias Económicas', 4.00, 9.00, '2025-1\n1. Conferencia Virtual Internacional: Herramientas y tecnologías para la planificación de destinos turísticos sostenibles.\n2. Feria Universitaria de Turismo FUTUR 2025.\n3. SEMINARIO PERMANENTE DE LOS ODS: "Una mirada al Caribe desde la perspectiva del proyecto Afro ODS: Cerrando brechas".\n4. Conferencia Virtual Internacional: “Turismo y Tecnología: La Revolución Digital en el Sector.\n\n2025-2\n5. III Seminario de Economía Internacional “Internacionalización de la economía colombiana y desempeño sector exportador del Departamento del Atlántico”\n6. II Seminario Internacional: Desarrollo Sostenible del Turismo Deportivo en los Bordes Costeros.\n7. I Ciclo de Conferencias: Economía, Política y Territorio Latam.\n8. Conferencia Virtual Internacional: “Turismo de identidad: El Rol de las lenguas nativas en la sostenibilidad cultural”\n9. Semana Colombo China.\n10. Pre congreso de Investigadores de la Red Iberoamericana RITMMA: “El Emprendimiento y la Innovación Como Elemento Dinamizador de la Sociedad”\n11. IV Network de Métodos Cuantitativos en Economía.\n12. Primer encuentro de modelo de las naciones unidas: Turismo, cultura y patrimonio.\n13. Conferencia: El rol del contador en la era de la Sostenibilidad: de la Materialidad Financiera a la Conectividad de la Información'),
(14, 'Ciencias Humanas', 9.00, 6.00, '"Ciencias Humanas (3):\nII Foro: Educación cultura y carnaval. Homenaje a Jairo Soto Hernandez\nLa escritura científica en la era de la IA: Oportunidades Ciencias Humanas (3):\nII Foro: Educación cultura y carnaval. Homenaje a Jairo Soto Hernandez\nLa escritura científica en la era de la IA: Oportunidades y amenazas en la presentación de trabajos académicos.\nHerencia viva, celebrando nuestra historia\n\nFilosofía (3): \nMemorias, experiencias y pedagogías para la paz\nNotas sobre Estética y filosofía de la Música\nFilosofia en red: Idealismo trascendental en Edmund Husserl\n\nHistoria (3): \nDinamicas y transformaciones urbanas que inciden en la calidad de vida del barrio san isidro en la ciudad de barranquilla por acciones de adjudicacion estatal de predios urbanos\nDe la historia clasica a la historia publica: el historiador en espacios no academicos\nXV Seminario de Historia del Caribe colombiano: historias e historiografías más allá del Caribe.\n\nMaestría en Estudio de Genero y Violencia (1):\nMaternidades: Diálogos y perspectivas feministas\n\nSociología (4)\nLo territorial y lo local en los paises de la región andina, centro america y el caribe\nLa importancia de la comunicación científica en las ciencias humanas\nSeminario Internacional Centenario Orlando Fals Borda\nVIII Seminario de Patrimonio Cultural Marítimo\n\nMaestría en Linguistica (1)\nEthos Discursivo y Ethos Prediscursivo en el analisis del discurso'),
(14, 'Ciencias Jurídicas', 5.00, 1.00, 'Ciencias Políticas (4):\nImportancia de la Reforma al sistema general de participaciones\nI Jornadad de Antropología, Política y Jurídica\nUna mirada hacia adelante... sin ignorar el pasado Encuentro nacional de facultades y programas de ciencias politicas\nDerecho (2):\nEstado Actual de los partidos políticos en Colombia\nII Escuela Latinoamericana de Ciencias Penales – EVBAQ 2025'),
(14, 'Educación', 14.00, 2.00, 'Licenciatura en Educación Especial (2): \nIV Simposio sobre Síndromw de Down mas oportunidades mas inclusión\nPasado, presente y futuro de la Educaciön especial en Colombia\n\nLicenciatura en Lenguas Extranjeras (2):\nEntrevista sobre la cultura Francófona\nSemana de la Francofonía\n\nLicenciatura en Ciencias Sociales (2):\nIII Semana de la Licenciatura en Ciencias Sociales\nInteligencia artificial y pedagogía: Exploración de nuevas fronteras en el aprendizaje\n\nLicenciatura en Matematicas (7):\nInvestigar a partir de relatos escritos\nLa resolución y el planteamiento de problemas en la formación de profesores de matemáticas \nAplicaciones de las matemáticas en nuestra cotidianidad\nmodelos matemáticos y aplicaciones de IA en los Agronegocios para mejorar la productividad.\nCaracterísticas de un profesor de matemáticas excelente\nDía del licenciado en Matemáticas 2025\nXVIII Feria TIC en educación matemática y XVI didáctica de las matemáticas \n\nMaestría en Educación (1):\nLa escritura cientifica en la era de la IA: Oportunidades y amenazas en la presentación de trabajos academicos\n\nMaestría ren Neuropedagogía (1):\nVI Congreso Internacional de Neuropedagogía, Innovaciones didácticas y procesos de inclusión educativa 2025-2: Programa Licenciatura en Educación Fisica, recreación y dedportes: Misión académica en India y España con el Grupo GIDEPRLS y Semillero CUMOINDE'),
(14, 'Ingeniería', 3.00, NULL, 'Para 2025-1, se desarrollaron los siguientes eventos:\n\n1. Se llevó a cabo la Jornada Técnica por el Día Mundial de la Seguridad y Salud en el Trabajo, titulada "Avances y desafíos en Seguridad Vial", con la participación del orador Manuel Eduardo Silva Rivera, dirigida al programa de Ingeniería Industrial. Esta actividad fue organizada en modalidad virtual en colaboración con el Instituto Mexicano del Transporte: Coordinación de Seguridad y Operación del Transporte, impactando a un total de 295 asistentes.\n\n2. Se realizó la Conferencia Internacional: La Seguridad y Salud en el Trabajo en Latinoamérica: Caso México, con el orador Carlos Humberto Ceballos Canché, orientada al programa de Ingeniería Agroindustrial. Esta conferencia se desarrolló en modalidad virtual, con el apoyo del Ministerio del Transporte de México, beneficiando a 20 estudiantes de último semestre de la Facultad de Ingeniería.\n\n3. Se dictó el Curso de Procesos Modernos de Manufactura de Materiales Metálicos, a cargo del orador José María Cabrera Marrero, enfocado en el programa de Ingeniería Mecánica. Esta actividad fue realizada de manera presencial, gracias a la alianza entre docentes de la Universidad del Atlántico y la Universidad Politécnica de Cataluña, impactando a más de 200 estudiantes del programa de Ingeniería Mecánica.'),
(14, 'Ciencias de la Salud', 3.00, 1.00, 'En este período académico 2025-1 se realizaron tres (3) eventos extracurriculares donde participaron ponentes internacionales: \n-WEBINAR INOCUIDAD ALIMENTARIA: CIENCIA EN ACCION (conferencista de Brasil), \n-CAFÉ POR LA SALUD (conferencista de Alemania) \n-ÉTICA PROFESIONAL PARA LA PUBLICACIÓN DE ARTÍCULOS CIENTÍFICOS (conferencista de Bolivia). Sumit de la innovacion y colaboracion para combatir la enfermedad respiratoria 30 de septiembre.'),
(14, 'Química y Farmacia', 1.00, 2.00, '1. Jornada Nacional de Farmacocinetica Clínica de Antimicrobianos. Invitado: Paulo Caceres de Argentina. \n\n2. XXV Semana cientifica y XII Feria de Emprendimiento e Innovación Farmaceutica. Invitada: Rosalba Pantoja de Brasil. Conferencia: Inteligencia artificial aplicada a procesos en la industria farmaceutica. \n\n3. Realización de dos clases espejo en asocición con la Universidad UNIBE de Costa Rica. Participación del docente Oscar Camacho Uniatlantico el dia 29-10-2025 y del docente Jose Luis Sanchez de la UNIBE el dia 05-11-2025. Temas relacionados con la homeopatia.'),
(16, 'Arquitectura', 5.00, NULL, 'Facultad de Arquitectura : 5\n1. Luz Adriana Iriarte López, Programa Arquitectura, "Aula invertida para el estudio de las tipologías arquitectónicas en los periodos colonial y republicano", 2. Luz Adriana Iriarte López Programa Arquitectura, "Aprender con la mirada: la fotografía como recurso didáctico en el aula de Historia de la Arquitectura y el Urbanismo en el caribe colombiano". \n3. Giovanni Jose Isoza Navarro Programa: Técnica profesional en construcción de proyectos arquitectónicos. "El Barroco: formas, símbolos y espacio en una clase invertida". \n4. Roberto Rodríguez Castilla Programa Arquitectura, "Capturar el mundo, despertar ideas: la fotografía en la Arquitectura".\n5. Giovanni Jose Isoza Navarro Programa: Técnica profesional en construcción de proyectos arquitectónicos. Elaboración de Ebook. Aplicación de Tecnologías en el proceso de Diseño Arquitectónico.'),
(16, 'Bellas Artes', NULL, 2.00, 'Para el año 2025 se recibió informe de 23 docentes adscritos a la facultad sobre las prácticas de innovación educativas con TIC desarrolladas en su desarrollo del currículo, de estás 23, solo 1 participó en el evento organizado por la oficina de virtualización, por lo cual esta oficina reporta medición de cumplimiento de 1 docente y la docente Ángela Marín:\n• El docente Jorge Iván Suarez Bellas Artes/Arte Dramático participó en el evento organizado por la oficina de virtualización, con la experiencia ‘Pedagogías Inmersivas: Realidad Virtual y Enseñanza Artística en el Programa de Arte Dramático.\n• La profesora Angela Marín/Licenciatura en Música fue seleccionada por el Departamento de Educación Virtual y la Oficina de Innovación y Transferencia tecnológica para representar a la universidad en el evento Colombia 4.0 organizado por MinTics. Ella fue la única docente de la Universidad del Atlántico que participó en este evento nacional. \n\nImplementadas en la Facultad:\n1. Nubia Florez y Wilfran Barrios (Repertorio y Montajke: Diseño de vestuario para la obra Chicago a partir de prácticas de innovación tecnológica educativa.\n2. Tania Iglesias (Psic. Del Dllo.): uso de plataformas virtuales de aprendizaje que integran contenidos asincrónicos (lecturas, videos, presentaciones interactivas) y actividades sincrónicas (encuentros virtuales, foros de discusión, talleres en línea). \n3. Arlington Pardo (Laboratorio): Aplicacion de elementos tecnologicos en la elaboracion de de instrumentos ancestrales y tecnicas de interpretacion. \n4. Milton Vasquez (Actuación): Herramientas audiovisuales tecnológicas y el apoyo de la Inteligencia Artificial como laboratorio de narrativas.\n5. Alexander Osorio (Tenis de Campo): Se utilizaron herramientas digitales como videos didácticos, aplicaciones móviles para analizar el movimiento y el rendimiento en cancha, y recursos en línea para el seguimiento de progresos, al igual que la gamificación del aprendizaje por medio de videojuegos. \n6. Alexander Osorio (Lúdica): Se utilizaron recursos digitales como juegos interactivos, plataformas para creación de actividades lúdicas, (Kahoot, Genially), y videos educativos.\n7. Alexander Osorio (Inv. Formativa): se emplearon recursos como la inteligencia artificial (IA) para la búsqueda y organización de información relevante, y plataformas como Canva para la elaboración de trabajos visuales y presentaciones creativas\n8. María Reales (Repertorio III): Con el software Isadora, se plantearon videos que interrelacionaban la escena en algunos momentos concretos, Durante el semestre se activo la manera de dialogar con la imagen audiovisual. \n9. Yanni Manotas (Taller Inv. Danza): La asignatura integra herramientas digitales como Notion, Padlet y Google Drive para fortalecer la documentación, organización y reflexión de los procesos de investigación-creación. Notion se utiliza como bitácora digital integral; Padlet facilita la socialización de ideas y el trabajo colaborativo; y Drive permite almacenar y compartir materiales audiovisuales y escritos. \n10. Yanni Manotas (Comp. coreográfica): Destacó el uso de la app Choreographic, que permitió a los estudiantes experimentar con el diseño del espacio escénico, trayectorias, niveles y relaciones de movimiento, facilitando una comprensión visual de los principios compositivos.\n11. Angela Marín (Histomúsica III):Por la naturaleza del curso, virtual, las clases incluyeron este tipo de prácticas. Los estudiantes navegaron por diversos OVAS, que se diseñaron siguiendo la estrategia Aprendizaje a través de escenarios. \n12. Angela Marín (Ed. InclusivaI):os estudiantes diseñaron un material educativo-musical desde los principios del DUA con el uso de las IAs. \n13. Jorge I. Suárez (Escenografía): Mini taller Ai en la plastica escénica, e ingeniería de prompt\n14. Jairo Atencia (Folclor): entre las practicas desarrolladas encontramos gamificación, Inteligencia Artificial, interacción con medio audiovisuales.\n15. Roberto Camargo (Ensamble): utilizacion de pistas para el acompañamiento del canto, utilizando el programa Moises y la utilizacion de microfonos para la aplificacion de sus voces\n16. Vanessa Fontalvo (Proyecto de Grado): los estudiantes implementaron la revisión de redacción de sus proyectos con IA.\n17. Anibal Maldonado (Taller integral de Arte): Los estudiantes trabajaron una animación experimental con diferentes técnicas digitales y analógicas. \n18.Edward Yepes (Solfeo): Utilización de la app RIEDPRO\n19. Marisol Córdoba (Coro): Se usaron aplicaciones móviles (como TonalEnergy, Voice Tools y Warm Me Up!) para la práctica autónoma de la técnica vocal, afinación y respiración.\n20. Ana Navarro (Investigación): Se utilizaron la herramienta de mapas conceptuales herramientas de Padlet.\n21. Fabiola Hernández (Anteproyecto): Se utilizaron herramientas ofrecidas por la IA para generar presentaciones prospectivas en imágenes digitales de la organización final del anteproyecto de grado.\n22. Nubia Florez (Estudios Interculturales): Trabajaron un padlet colaborativo sobre Cuerpo caribe anexo el link https://padlet.com/saelmera/cuerpo-caribe-estudios-interculturales-2-iawxtzomeqyvb9cj \n23. Lou Robinson (Proy. de grado): Se utilizaron plataformas de inteligencia artificial para realizar asistencias a la investigación.'),
(16, 'Ciencias Básicas', 1.00, 5.00, '2025-1\n- Implementación de pagina Web con simulaciones para practicas de laboratorio de óptica (Francisco Racedo)\n\n2025-2\n- Uso de la Inteligencia artificial (IA) como herramienta clave para potenciar la educación superior - Programa de Matemáticas (Julio Romero y Kennedy Hurtado)\n- Cuarto encuentro de innovación educativa mediada por TIC - docente Sandy Garcia y Tulio Diaz Pertuz\n- Diseño y publicación de E-Books interactivos (Tulio Diaz Pertuz)\n- Plan de formación semilleros de investigación RediSIA 2025 (Gustavo Quintero)\n- Estadística 4.0: Innovación Educativa Con IA y Recursos Digitales en Sociología (Docente Ernesto Varela)'),
(16, 'Ciencias Económicas', 5.00, 2.00, '2025-1\nAna Elena Vega Consuegra, PROGRAMA: Técnico Profesional en Operación Turística, "Descubriendo las etapas del proceso administrativo en una clase invertida". Edinson Enrique Marenco Alarcón Programa: ECONOMIA, Estudio técnico de proyectos de inversión: decisiones que se construyen desde una clase invertida. Yanyn Aurora Rincón Quintero, Programa: Técnico Profesional en Operación Turística. María del Pilar Soles sanguino, Programa: Tecnología en Gestión Turística - Por Ciclos propedéuticos "Convencer viajando: argumentos de venta de productos turísticos en una clase invertida". YIRA BEATRIZ ALVARADO TRESPALACIOS. Programa: Administración de Empresas Turísticas. "Ver para comprender la industria turística". María del Carmen Sosa. Programa: Administración de Empresas "Apalancamiento financiero: una mirada activa desde el aula invertida".\n2025-2\nLas TIC Como Mediadoras Para el Desarrollo del Pensamiento Crítico, la Creatividad y la Resolución de Problemas - Yira Alvarado.\nEsquemas Conceptuales En Diagrams.Net Como Estrategia De Innovación Didáctica Para El Aprendizaje Significativo En Contaduría Pública - Jose Mora'),
(16, 'Ciencias Humanas', 1.00, 2.00, '1- (Muriel Jiménez) La Enseñanza de la Historia Digital y las Herramientas Digitales Aplicadas a la Investigación Histórica: Reflexiones Desde la Práctica 2- (Yamileth Betancourt): Retos y Aprendizajes en la Puesta en Marcha del Primer Programa Virtual Intérprete de Lengua de Señas en la Universidad del Atlántico 3- (Arturo Cardozo) Filosofía Online'),
(16, 'Ciencias Jurídicas', 1.00, NULL, 'Ciencias Jurídicas: 1\nJanice Cotes Hereira,\nPrograma: Derecho,\n"Innovar y proteger: una clase invertida sobre los derechos de la propiedad industrial"'),
(16, 'Educación', 13.00, 2.00, '2025-1: 13\nPrograma: Licenciatura en Lenguas Extranjeras con Énfasis en inglés y francés:\nDerly Cervantes Cerra "Descubre el femenino en francés: estrategia de aula invertida para sustantivos y adjetivos". \nEdwin De la Paz Padilla: "La Sonoridad". \nNancy Camargo Rodelo “Aprende Assessment Formativo con Clase Invertida”\nMaría del Carmen Fontalvo Cantillo. "Click al conocimiento del alemán ".\n\nPrograma: Licenciatura en Educación Infantil. \n Rosaura Miranda Padilla\n"Enseñar con imágenes: el poder didáctico de la fotografía en la clase de Epistemología de la pedagogía \n\nPrograma: Licenciatura en Humanidades y Lengua Castellana: \nBrenda Valentina Pianeta Cantillo. \n"Fotografía para pensar, sentir y aprender: estrategias visuales en el aula de Alfabetización inicial ". \nRocío Varela Arregocés. "Evaluar con otros ojos".\n\nPrograma: Licenciatura en Educación Especial: \nDaniela oliveros Diaz. \n "Educar con luz: la fotografía al servicio del aprendizaje significativo". \nLiliana Beatriz Herrera Nieves\n "La imagen como punto de partida en la historia de la Educación especial ".\nVerónica De la Hoz Vargas. \n"Fotografía educativa: una herramienta para el análisis y la reflexión en la investigación y la práctica pedagógica". \nLucía Fernanda Ferrel Ballestas.\n"Educar con luz: la fotografía al servicio del aprendizaje significativo".\nPrograma: Licenciatura en Educación artística.\nJuan Pinto "Fotografía: base fundamental de la comunicación audiovisual". Programa: Lic. en Idiomas Extranjeros: Mayra Alejandra Diaz De La Cruz, Adriana Patricia Álvarez Rodríguez - "Voces Multilingües: Un Laboratorio De Lenguas A Través del Podcast". Programa lic. en Educación Fisica: Mónica Lindo De Las Salas - "Una experiencia como editora"'),
(16, 'Ingeniería', 2.00, NULL, 'CARLOS ALBERTO PALACIOS PÉREZ, Programa: Ingeniería Mecánica. "Del punto al plano: una clase invertida sobre proyecciones en geometría descriptiva". \n\nIVAN DARIO MERCADO MARTINEZ. Programa:Ingeniería Agroindustrial, "El ambiente bajo la lupa: una introducción invertida al impacto ambiental"'),
(16, 'Ciencias de la Salud', 1.00, NULL, 'En este período académico la docente Mariela Laurens realizó con los estudiantes el diseño de video educativo para la promoción de la salud en el adulto joven (PROMOVIENDO ESTILOS DE VIDA SALUDABLE EN EL ADULTO JOVEN). Esta actividad se realizó con el acompañamiento del Departamento de Educación Virtual'),
(16, 'Química y Farmacia', 0.00, 1.00, 'Participación de los docentes Juan Camilo Perez (Inteligencia artificial generativa: una aproximación a la practica profesional) y Tulio Diaz (Cuando La Ciencia Canta y la IA Inspira: Nuevas Pedagogías en Microbiología) en el IV Encuentro de practicas docentes e innovación educativa mediada por las TIC. 23 y 24 de septiembre Centro Cultura UA.'),
(24, 'Arquitectura', 1.00, NULL, 'En la sesión del Consejo Superior del 13 de mayo de 2025 se aprobó el programa Diseño Creativo, articulado en Ciclo Propedéutico con los programas Técnica Profesional en Comunicación Gráfica y Tecnología en Comunicación Digital y Mercadeo. Este programa fue radicado en la plataforma SACES del Ministerio de Educación Nacional el 9 de octubre y alcanzó estado de completitud el 11 de noviembre. Actualmente, se encuentra en espera del otorgamiento del Registro Calificado, requisito indispensable para su oferta en la nueva sede del municipio de Soledad.'),
(24, 'Bellas Artes', NULL, NULL, 'N/A'),
