-- ═════════════════════════════════════════════════════════════════════════════
-- SEGUIMIENTO de "FOR-DE-144 Corte periodo academico 2025.xlsx" en el formulario "Plan de Acción 2025"
--   · SEMESTRE 1 del Excel  → TRIMESTRE 2 (T2)
--   · SEMESTRE 2 del Excel  → TRIMESTRE 4 (T4)      (T1 y T3 quedan vacíos)
--   · Logros, límites, observación y acciones de fortalecimiento de cada indicador.
--   · Seguimiento por facultades (semestre 1, semestre 2 y descripción de cada facultad).
--
-- Antes de ejecutar:
--   1. Ya debe estar cargada la formulación (2025formu.sql) y SIN duplicados: el formulario debe tener exactamente 207 indicadores
--      del año 2025 (usa 2025formu_quitar_duplicados.sql si hace falta). Si no, el script no hace nada y te lo dice.
--   2. Haz un respaldo de la base de datos.
--   3. Ejecuta TODO el archivo de una vez (usa variables @).
--   4. @es es el estado en que quedan los cuatro trimestres:
--        2 = APROBADOS (reportados, cuentan en el cumplimiento)  ← por defecto, es un corte ya cerrado
--        0 = BORRADORES (hay que enviarlos a revisión y aprobarlos en el sistema)
--
-- Se puede ejecutar más de una vez: vuelve a escribir los mismos valores (no duplica nada).
-- Los semestres, la meta ejecutada y el % de avance se calculan aquí con las mismas reglas del sistema (según el tipo de medición).
-- Valores de indicadores en porcentaje: el Excel los guarda como fracción (0.09 = 9 %) y aquí quedan como «9%».
-- ═════════════════════════════════════════════════════════════════════════════
SET NAMES utf8mb4;
SET @es = 2;

SET @f = (SELECT formulario_id FROM formulacion_144 WHERE anio = 2025 AND creado_por = 1 GROUP BY formulario_id ORDER BY COUNT(*) DESC LIMIT 1);
SET @n = (SELECT COUNT(*) FROM formulacion_144 WHERE formulario_id = @f AND anio = 2025 AND creado_por = 1);
SET @base = (SELECT MIN(id) FROM formulacion_144 WHERE formulario_id = @f AND anio = 2025 AND creado_por = 1) - 1;
-- Control: los ids van seguidos y el primero y el último indicador son los esperados
SET @ok = IF(@n = 207 AND (SELECT COUNT(*) FROM formulacion_144 WHERE formulario_id = @f AND id BETWEEN @base + 1 AND @base + 207) = 207
             AND (SELECT nombre_indicador FROM formulacion_144 WHERE id = @base + 1) = 'Nivel de inglés de los docentes de carrera profesoral'
             AND (SELECT nombre_indicador FROM formulacion_144 WHERE id = @base + 207) = 'Dotación de espacios para el desarrollo de las actividades académico administrativas', 1, 0);

SELECT @f AS formulario_id, (SELECT titulo FROM formularios WHERE id = @f) AS titulo, @n AS indicadores_encontrados, @ok AS control_ok,
       IF(@ok = 1, 'Todo en orden: se cargará el seguimiento', 'NO SE CARGA NADA: el formulario no tiene exactamente los 207 indicadores seguidos (¿duplicados?)') AS mensaje;

-- Tabla de apoyo con el seguimiento de cada indicador (n = N° del Excel)
DROP TABLE IF EXISTS tmp_seg_2025;
CREATE TABLE tmp_seg_2025 (n INT PRIMARY KEY, t2 VARCHAR(40), t4 VARCHAR(40), s1 DECIMAL(14,2) NULL, s2 DECIMAL(14,2) NULL,
                           ejecutada DECIMAL(14,2), avance DECIMAL(14,2), logros TEXT, limites TEXT, observacion TEXT, acciones TEXT) DEFAULT CHARSET=utf8mb4;

-- Seguimiento del indicador: S1 en T2, S2 en T4
UPDATE formulacion_144 f JOIN tmp_seg_2025 s ON f.id = @base + s.n
SET f.trimestre1_seguimiento = NULL, f.trimestre2_seguimiento = s.t2, f.trimestre3_seguimiento = NULL, f.trimestre4_seguimiento = s.t4,
    f.semestre1_seguimiento = s.s1, f.semestre2_seguimiento = s.s2, f.meta_ejecutada = s.ejecutada, f.porcentaje_avance = s.avance,
    f.logros = s.logros, f.limites = s.limites, f.observacion_estado = s.observacion, f.acciones_fortalecimiento = s.acciones,
    f.estado_seguimiento = @es, f.solicitud_estado_seguimiento = IF(@es = 2, 1, 0), f.semaforo_etapa_seguimiento = IF(@es = 2, 4, 0),
    f.semaforo_rechazo_etapa_seguimiento = 0, f.fecha_publicacion_seguimiento = IF(@es = 2, NOW(), NULL)
WHERE @ok = 1;

-- Estado de cada trimestre (el seguimiento se aprueba por trimestre)
CREATE TABLE IF NOT EXISTS seguimiento_trimestres_144 (
    formulacion_id INT NOT NULL, trimestre TINYINT NOT NULL, estado TINYINT NOT NULL DEFAULT 0, solicitud TINYINT NOT NULL DEFAULT 0,
    semaforo_etapa TINYINT NOT NULL DEFAULT 0, semaforo_rechazo_etapa TINYINT NOT NULL DEFAULT 0, fecha_publicacion DATETIME NULL,
    fecha_actualizacion DATETIME NULL, PRIMARY KEY (formulacion_id, trimestre)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM seguimiento_trimestres_144 WHERE @ok = 1 AND formulacion_id BETWEEN @base + 1 AND @base + 207;
SELECT f.id, t.n, @es, IF(@es = 2, 1, 0), IF(@es = 2, 4, 0), 0, IF(@es = 2, NOW(), NULL), NOW()
FROM formulacion_144 f
JOIN (SELECT 1 AS n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4) t
WHERE @ok = 1 AND f.id BETWEEN @base + 1 AND @base + 207;

DROP TABLE IF EXISTS tmp_seg_2025;

-- Seguimiento por facultades (semestre 1, semestre 2 y descripción de la gestión)
DROP TABLE IF EXISTS tmp_segfac_2025;
CREATE TABLE tmp_segfac_2025 (n INT, facultad VARCHAR(60), s1 DECIMAL(14,2) NULL, s2 DECIMAL(14,2) NULL, descripcion TEXT NULL) DEFAULT CHARSET=utf8mb4;

-- La facultad se busca por nombre en la tabla facultades. Si ya tenía distribución se conserva; si no, se crea con distribución 0.
SELECT @base + g.n, (SELECT fa.id FROM facultades fa WHERE fa.nombre LIKE CONCAT('%', g.facultad, '%') ORDER BY fa.id LIMIT 1), '', 0, g.s1, g.s2, g.descripcion
FROM tmp_segfac_2025 g
WHERE @ok = 1 AND (SELECT fa.id FROM facultades fa WHERE fa.nombre LIKE CONCAT('%', g.facultad, '%') ORDER BY fa.id LIMIT 1) IS NOT NULL
ON DUPLICATE KEY UPDATE seguimiento_sem1 = VALUES(seguimiento_sem1), seguimiento_sem2 = VALUES(seguimiento_sem2), seguimiento_descripcion = VALUES(seguimiento_descripcion);

DROP TABLE IF EXISTS tmp_segfac_2025;

-- Verificación: indicadores con seguimiento cargado y cuántos trimestres quedaron (debe dar 207 indicadores y 4 trimestres cada uno)
SELECT COUNT(*) AS indicadores_con_trimestres, MIN(c) AS min_trimestres, MAX(c) AS max_trimestres
FROM (SELECT formulacion_id, COUNT(*) AS c FROM seguimiento_trimestres_144 WHERE formulacion_id BETWEEN @base + 1 AND @base + 207 GROUP BY formulacion_id) x;
